"""Stop-lists for the Chuvash game (Yandex Games rule 3.4.5: no references to religion; plus profanity / adult / alcohol / death).
Covers Christian, Islamic AND traditional Chuvash pagan vocabulary (deities, spirits, sacrifices, shamans, funerary rites).
Used by lexicon.py / build_game.py / scan_religion.py to keep such words out of crosswords, daily puzzles, bonus words, word of the day and cards."""
import re
# Chuvash religious vocabulary. Exact words; stems are in STOP_RE.
STOP_WORDS = {
    # Christianity / Islam
    'турӑ', 'тура', 'туррӑ', 'турри', 'турра', 'турӑш', 'туррӑм', 'чиркӳ', 'чиркӳлле', 'пуп', 'пупсем', 'тиакӑн', 'хӗрес', 'хӗреслӗ', 'хӗресле', 'хӗреслен', 'кӗл', 'кӗлӗ', 'кӗлле',
    'кӗлту', 'кӗлтӑв', 'кӗлтума', 'кӗлӗҫӗ', 'сӑвап', 'сӑваплӑ', 'ҫылӑх', 'ҫылӑхлӑ', 'ҫылӑхсӑр', 'тамӑк', 'ҫӑтмах', 'мӑнкун', 'раштав', 'праҫник', 'ангел', 'монах',
    'мӑнастир', 'мӑнастирь', 'монастырь', 'икона', 'апостол', 'христос', 'христиан', 'тӗн', 'тӗнлӗ', 'тӗнсӗр', 'тӗне', 'тӗнӗ', 'тӗнпе', 'ислам', 'мечӗт', 'мечеть', 'мулла',
    'намаз', 'пророк', 'библи', 'библия', 'евангели', 'чан', 'чансем', 'хурал', 'ҫимӗк', 'кӗрсарни', 'сурхури', 'сурхурӑ', 'мӑнкунлӑх', 'покров', 'турӑҫ',
    # pagan Chuvash: deities, spirits, sacrifice, shamans, sorcery
    'киремет', 'кирлемет', 'чӳк', 'чук', 'чӳкле', 'чӳклеме', 'чӳкӗ', 'ирӗх', 'ирих', 'йӗрӗх', 'йӑрӑх', 'пӳлӗх', 'пӳлӗхҫӗ', 'пӳлӗхӗ', 'хӗрт-сурт', 'хӗртсурт',
    'юмӑҫ', 'йӑмӑҫ', 'юмӑҫӑ', 'тухатмӑш', 'тухатмӑшӗ', 'асамҫӑ', 'асам', 'усал', 'усалсем', 'шуйттан', 'шуйттанӗ', 'арҫури', 'вупкӑн', 'вупӑр', 'албасты', 'йӑван', 'келе',
    'курасса', 'хӗвелтурӑ', 'кӗлӗ', 'туррӑн', 'ҫӗршыв-турӑ', 'кӗлтӳ', 'ӗрӗх', 'вӑрӑ-хурах', 'мунчаҫӑ', 'аллах', 'алла', 'ахун', 'имам', 'шайтан', 'хаджи', 'хаҫрет', 'мӑчӑт', 'кӗлӗ', 'ҫӑва', 'ҫӑвасем', 'ҫӑварни', 'пасха', 'храм', 'святой', 'ӗҫкӗ', 'ӗҫке', 'ӗҫкӗҫӗ', 'хуралҫӑ', 'манара', 'пӗтӳ',
    # funerary
    'масар', 'масарӗ', 'юпа', 'тупӑк', 'вилӗ', 'вилӗм', 'вилес', 'вил', 'вилнӗ', 'вилли', 'виле', 'виллӗ', 'хурлӑх', 'хӑватсӑр',
    # alcohol
    'эрех', 'ерех', 'сӑра', 'ӳсӗр', 'ӳсӗрӗл', 'ӳсӗрле', 'хӑмла', 'пивӑ', 'кӑмака-эрех',
}
STOP_RE = re.compile(r'^(?:турӑ$|турӑш|турри$|туррӑ|чиркӳ|хӗрес|кӗл(?:ӗ|т[ӑу]|ле)|сӑвап|ҫылӑх|тамӑк|ҫӑтмах|мӑнкун|раштав|праҫник|ангел|монах|мӑнастир|христ|тӗн(?:л|с|не|ӗ$)|'
                     r'киремет|чӳк|ирӗх|йӗрӗх|пӳлӗх|юмӑҫ|тухатмӑш|асамҫ|шуйттан|арҫури|вупкӑн|вупӑр|албасты|масар|тупӑк|вил(?:ӗ|е|л|н|ес)|эрех|ерех|ӳсӗр)')
# Russian clue patterns (word-boundary aware, so богатый / крестьянин / огрех / черта / культура don't match)
GLOSS_RE = re.compile(r'(?<![а-яё])(?:'
    r'бог(?:а|у|ом|е|и|ов|ам|ами|ах|иня|ини|ине|иню)?(?![а-яё])|бож(?:еств|ий|ья(?! коровк)|ье|ьи|ниц)|богородиц|богомол|аллах|всевышн|'
    r'жрец|жреч|молит|молен|молельщ|молеб|молельн|моления|намаз(?!ан|ыв|ать)|пророк|коран|ислам|мусульман|мечет|минарет|медресе|шариат|муэдзин|хадж|паломн|'
    r'церк|христ|ангел|дьявол|сатан|шайтан|джинн|демон|нечисть|нечист(?:ая|ой|ую) сил|злой дух|бес(?:а|ы|ов|ам)?(?![а-яё])|чёрт|'
    r'ад(?:а|у|ом)?(?![а-яё])|ра(?:й|я|ю|ем)(?![а-яё])|загробн|судный|воскрес(?:ени|л)|греш|грех|свят|священ|причащ|рождеств|икон|'
    r'крест(?!ьян|ов[кн]|оцвет|ц|ец|ообраз)|креще|жертвопринош|жертвовател|религ|вероучен|верующ|вероотступ|язычес|язычник|культ(?:а|ов|у|ом|е|овый|овое|овая)?(?![а-яё])|'
    r'храм|монах|монаш|мулл|имам|поп(?:а|у|ом|ы|ов)?(?![а-яё])|пасх|троиц|идол|шаман|колдов|колдун|ведьм|знахар|гадал|гадани|магии|магия|заклинан|'
    r'(?<![а-яё])(?:в|из|у|о)?язычес|языческ|идолопоклон|духов предков|дух(?:а|у|ом)? (?:предков|леса|дома|воды|бани)|жертвенн|моленье|кереметь|похорон|покойн|кладбищ|могил(?!ьник)|саван|поминк|мертвец|усопш|'
    r'пост(?:ить|иться)|разговлен|благословен|проклят|милостын|ниспослан|обет(?:а|ы)?(?![а-яё])|чудотвор|поклоня|поклонени|гада(?:ть|ю|ние)|предсказ|заговарив|призрак|привидени|предопредел|предначерт|(?<![а-яё])рок(?![а-яё])|обряд|ритуал|кябин|мифологич|мифическ|божество|святилищ|колокол|звонниц|колокольн|монастыр|причт|дьякон|диакон|священник|архиере|литурги|богослужен|евангел|библи(?!отек)|апостол|покров(?:а|ом)? (?:день|праздник)|пасх|семик|радониц|поминов|будд|индуизм|иудаизм|зороастр|конфесс|мифолог|митраизм|теолог|богослов|атеизм|адхан|азан'
    r')', re.I)

# profanity / adult / drugs / violence (Russian clue roots and Wiktionary labels) + a few Chuvash roots
BAD_RU = re.compile(r'(?<![а-яё])(?:хуй|хуе|хуё|пизд|ебат|ебан|ёб|бляд|блят|сука|суки|жоп|говн|дерьм|срат|ссат|мудак|мудил|пидор|педик|шлюх|гандон|залуп|'
                    r'дурак|глупец|тупиц|болван|дура(?![а-яё])|идиот|урод|дебил|кретин|негр(?!амот)|жид(?!к)|нацист|фашист|наркот|героин|убий|убить|убива|труп|смерт|секс|порн|'
                    r'член(?: тела)?(?= мужск)|половой|половые|половых|испражн|кал(?![а-яё])|навоз|моча|мочи|мочиться|задниц|ягодиц|анус|задний проход|'
                    r'блуд|разврат|распут|проститут|любовни|изнасил|водк|самогон|пьян|алкогол|спиртн|вино(?![а-яё])|винн|пив(?:о|а)(?![а-яё])|окурок|сигарет|табак|опьян|самоубий|казн(?:ь|ить|и(?![а-яё]))|виселиц|палач|'
                    r'penis|vagina|vulgar|offensive|derogatory|feces|faeces|urine|sexual)', re.I)
BAD_LABELS = ('бран.', 'груб.', 'вульг.', 'неценз.', 'презр.', 'обсц.', 'мат.', 'религ.', 'мифол.', 'церк.', 'рел.', 'пренебр.')
BAD_TT = re.compile(r'^(?:пӗҫӗ|кутӑн(?:ла)?$|кут(?:ӗ|ран|на)?$|сысна-?кут|ӗҫке|пӗҫерккӳ|шӑк$|шӑкӑ$|шӑк(?:ла|ӑр)$|ҫӗлен-шӑк|вӗлер|вӗлерӳ|вӗлерӳҫӗ|ӑсӑр|айван|ухмах|ухмаха?$)')

def religious(w, clue=''):
    w = w.lower()
    if w in STOP_WORDS or STOP_RE.match(w): return True
    return bool(clue and GLOSS_RE.search(clue.lower()))

def offensive(w, clue='', labels=''):
    if BAD_TT.match(w.lower()): return True
    if any(l in labels for l in BAD_LABELS): return True
    return bool(clue and BAD_RU.search(clue.lower()))
